using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using McpServer;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddHttpClient("WeatherApi", client =>
    {
        client.BaseAddress = new Uri("https://api.weather.example.com/");
    });

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Get the current weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");
        var forecast = await client.GetFromJsonAsync<WeatherResponse>(
            $"forecast?city={Uri.EscapeDataString(city)}", cancellationToken);

        return forecast is null
            ? $"No forecast data available for {city}."
            : $"{city}: {forecast.Summary}, {forecast.TemperatureC}°C";
    }

    [McpServerTool, Description("Get weather alerts for a US state (2-letter code).")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code, e.g. 'WA'")] string state,
        CancellationToken cancellationToken)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");
        var alerts = await client.GetFromJsonAsync<AlertResponse[]>(
            $"alerts?state={Uri.EscapeDataString(state)}", cancellationToken);

        if (alerts is null or { Length: 0 })
            return $"No active alerts for {state}.";

        return string.Join("\n", alerts.Select(a => $"⚠️ {a.Event}: {a.Headline}"));
    }
}

public record WeatherResponse(
    [property: JsonPropertyName("summary")] string Summary,
    [property: JsonPropertyName("temperatureC")] int TemperatureC);

public record AlertResponse(
    [property: JsonPropertyName("event")] string Event,
    [property: JsonPropertyName("headline")] string Headline);

